functions.example:
documentId = DOCUMENT_CREATE_FROM_JSON("{ 'this': 'is', 'a': [ { 'simple': 'test', 'another': 'add' } ] }")
DOCUMENT_DEL_PROPERTY_ON_OBJECT(documentId, "a[0]", "simple")
objectId = DOCUMENT_GET_OBJECT(documentId, "a[0]")
DOCUMENT_DEL_PROPERTY_ON_OBJECT(objectId, "another")
res = DOCUMENT_SERIALIZE(documentId, "json-indented")
RETURN(res)

Returns: 
{
  "this": "is",
  "a": [
    {}
  ]
}

